(()=>{'use strict';
const KEY=('eventspro-speaker-timer-v1:'+location.pathname.split('/').slice(0,-1).join('/')),C=EventsPROSpeakerTimer;let revision=-1,last='',control='',busy=false,offset=0;
const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);const client=sessionStorage.timerLANClient||(sessionStorage.timerLANClient=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join(''));
const api=async body=>{const r=await fetch('api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Sin conexión');return data;};
function save(data){revision=data.revision;offset=Date.now()-data.serverNow;const local={...data.state,deadline:data.state.running?data.state.deadline+offset:null};last=JSON.stringify(local);if(localStorage.getItem(KEY)!==last){localStorage.setItem(KEY,last);dispatchEvent(new StorageEvent('storage',{key:KEY,newValue:last,storageArea:localStorage}));}const badge=document.querySelector('#lan-status');if(badge)badge.textContent=data.remote.connected?'Control remoto vinculado: '+data.remote.device:'Companion conectado';if(data.remote.connected)document.querySelector('#lan-pairing')?.close();}
async function tick(){if(busy)return;busy=true;try{if(!control){const d=await api({op:'owner',client});control=d.control;save(d);}else{const raw=localStorage.getItem(KEY)||last;save(await api({op:'sync',client,revision,changed:raw!==last,state:{...JSON.parse(raw),deadline:JSON.parse(raw).running?JSON.parse(raw).deadline-offset:null},presets:JSON.parse(localStorage.getItem(KEY+'-presets')||'[]'),messages:JSON.parse(localStorage.getItem(KEY+'-messages')||'[]')}));}}catch(e){const b=document.querySelector('#lan-status');if(b)b.textContent=e.message;}finally{busy=false;setTimeout(tick,250);}}
const output=new URLSearchParams(location.search).get('nativeSpeaker')==='1';
if(output){(async function poll(){try{save(await api({op:'read',client}));}catch{}setTimeout(poll,500);})();return;}
function attach(){const target=document.querySelector('.st-header .suite-projects')||document.querySelector('.st-header');if(!target||document.querySelector('#lan-status'))return;const badge=document.createElement('span');badge.id='lan-status';badge.role='status';badge.style.cssText='color:#83e8ab;padding:10px';badge.textContent='Conectando con Companion';const button=document.createElement('button');button.textContent='Control móvil';button.onclick=()=>{if(!control)return;const dialog=document.createElement('dialog');dialog.id='lan-pairing';dialog.style.cssText='background:#14232c;color:white;border:1px solid #61727f;border-radius:12px;padding:24px';const label=document.createElement('h2');label.textContent='Escanea con el móvil';const qr=document.createElement('canvas'),close=document.createElement('button');close.textContent='Cerrar';close.onclick=()=>dialog.close();dialog.append(label,qr,close);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);EventsPROTimerQR.render(qr,new URL('mobile.html#timer-remote='+control,location.href).href);dialog.showModal();};target.append(badge,button);}
new MutationObserver(attach).observe(document.documentElement,{subtree:true,childList:true});attach();tick();
})();

